B.bdI=new A.eE("mus","Mus",B.k5,"Early Jurassic \xb7 Toarcian",B.f5,B.tf,B.ai,110,"\u062d\u062c\u0631 \u062c\u064a\u0631\u064a\u060c \u0648\u0623\u062d\u064a\u0627\u0646\u0627\u064b \u0639\u0631\u0648\u0642 \u0642\u0644\u064a\u0644\u0629 \u0645\u0646 \u0627\u0644\u0623\u0646\u0647\u0627\u064a\u062f\u0631\u0627\u064a\u062a.","Limestone, occasionally with minor anhydrite streaks.","\u0638\u0647\u0648\u0631 \u0637\u0628\u0642\u0629 \u062c\u064a\u0631 \u0633\u0645\u064a\u0643\u0629 \u062a\u062d\u062a \u0639\u0631\u0648\u0642 \u0627\u0644\u0623\u0646\u0647\u0627\u064a\u062f\u0631\u0627\u064a\u062a \u0627\u0644\u0644\u064a \u0641\u0648\u0643\u0647\u0627\u060c \u0648\u064a\u0647 Fast ROP.","A thick limestone bed below the anhydrite streaks above, with fast ROP.",B.ahh,B.Jj,"\u063a\u0627\u0632 H\u2082S \u0645\u0645\u0643\u0646.","H\u2082S may occur.",null,null,"\u0645\u0643\u0645\u0646 \u0646\u0641\u0637\u064a \u0628\u0628\u0639\u0636 \u0627\u0644\u062d\u0642\u0648\u0644.","Oil reservoir in some fields.",null,null)
B.bdz=new A.eE("adaiyah","Adaiyah",B.k5,"Early Jurassic \xb7 Toarcian",B.tf,B.f5,B.ai,130,"\u0623\u0646\u0647\u0627\u064a\u062f\u0631\u0627\u064a\u062a \u0648\u064a\u0647 \u0639\u0631\u0648\u0642 \u062d\u062c\u0631 \u062c\u064a\u0631\u064a.","Anhydrite with limestone streaks.","\u0638\u0647\u0648\u0631 \u0637\u0628\u0642\u0629 \u0623\u0646\u0647\u0627\u064a\u062f\u0631\u0627\u064a\u062a \u0633\u0645\u064a\u0643\u0629 \u0648\u064a\u0647 Slow ROP.","A thick anhydrite bed with slow ROP.",B.ahh,B.Jj,"\u063a\u0627\u0632 H\u2082S \u0645\u0645\u0643\u0646.","H\u2082S may occur.",null,null,null,null,null,null)
